"""What a command gives back. Generated by anything-anything."""

import json
from dataclasses import dataclass
from typing import Any


@dataclass
class Output:
    """Text for people, data (JSON-able) for --json and MCP clients, and an exit code."""

    text: str = ""
    data: Any = None
    exit: int = 0

    def print(self, as_json: bool = False) -> None:
        if as_json:
            data = self.data if self.data is not None else {"text": self.text}
            print(json.dumps(data, indent=2, ensure_ascii=False))
        elif self.text:
            print(self.text.rstrip("\n"))
